function buildLayers(rows) {
  const accepted = [];
  const provisionalSafe = [];
  const reviewRequired = [];
  const rejected = [];
  const blockedQuarantined = [];

  const safeRows = Array.isArray(rows) ? rows : [];
  for (const row of safeRows) {
    if (!row) continue;
    const assertions = Array.isArray(row.classified_assertions) ? row.classified_assertions : [];
