+    no_external_model_calls: true,
+    no_external_llm_vlm_api_calls: true,
+    no_remote_supabase_mutation: true,
+    no_frontend_ui: true,
+    no_production_rag_reindex: true,
+  };
+}
+
+function stateValues(item) {
+  return uniqueSorted([
+    item?.source_status,
+    item?.status,
+    item?.classification_status,
+    item?.layer,
+    item?.route,
+    item?.source_status_before_promotion,
+  ]);
+}
+
+function hasAnyState(item, states) {
+  return stateValues(item).some((value) => states.has(value));
+}
+
+function isRawCandidateLike(item) {
+  return hasAnyState(item, RAW_STATES) ||
+    item?.reason_codes?.includes?.('raw_candidate_not_promotion_eligible');
+}
+
+function isBlockedLike(item) {
+  return hasAnyState(item, BLOCKED_STATES);
+}
+
+function isRejectedLike(item) {
+  return hasAnyState(item, REJECTED_STATES);
+}
+
+function isHighRiskAssertion(item) {
+  return item?.risk_tier === HIGH_RISK_TIER || HIGH_RISK_PREDICATES.has(item?.predicate);
+}
+
+function hasContradiction(item) {
+  if (item?.conflict_state && item.conflict_state !== 'none') return true;
+  const reasonCodes = Array.isArray(item?.reason_codes) ? item.reason_codes : [];
+  const reasonFamilies = Array.isArray(item?.reason_families) ? item.reason_families : [];
+  return reasonCodes.some((code) => CONTRADICTION_REASON_CODES.has(code)) ||
+    reasonFamilies.includes('contradiction') ||
+    reasonFamilies.includes('direction') ||
+    reasonFamilies.includes('topic_family');
+}
+
+function evidenceFamilies(item) {
+  if (Array.isArray(item?.evidence_families)) return uniqueSorted(item.evidence_families);
+  if (Array.isArray(item?.independent_evidence_families)) {
+    return uniqueSorted(item.independent_evidence_families);
+  }
+  return [];
+}
+
+function hasEvidenceBundle(item) {
+  const bundle = item?.evidence_bundle;
+  if (!isObject(bundle)) return false;
+  return [
+    bundle.evidence_refs,
+    bundle.evidence_atoms,
+    bundle.refs,
+    bundle.source_artifact_refs,
+  ].some((refs) => Array.isArray(refs) && refs.length > 0);
+}
+
+function missingProvenanceFields(item, requiredFields) {
+  const provenance = item?.provenance;
+  if (!isObject(provenance)) return requiredFields;
+  return requiredFields.filter((field) => {
+    const value = provenance[field];
+    if (Array.isArray(value)) return value.length === 0;
+    return value === null || value === undefined || value === '';
+  });
+}
+
+function validatorPassed(item) {
+  return item?.validator_passed === true ||
+    item?.triangulation_validator_route === 'pass' ||
+    item?.validator_status === 'pass';
+}
+
+function hasSampledQaOrReview(item) {
+  return item?.sampled_qa_passed === true ||
+    [
+      'approved',
+      'accepted',
+      'reviewed_accepted',
+      'human_approved',
+    ].includes(item?.human_review_state);
+}
+
+function meetsEvidenceThreshold(item, layer) {
+  const families = evidenceFamilies(item);
+  if (layer === 'accepted' && item?.risk_tier === LOW_RISK_TIER) {
+    return families.length >= 2 && families.includes('official_syllabus_objective') &&
+      item?.official_source_backed === true;
+  }
+  if (layer === 'accepted') {
+    return families.length >= 2;
+  }
+  if (item?.risk_tier === HIGH_RISK_TIER) {
+    return families.length >= 3;
+  }
+  return families.length >= 2;
+}
+
+function addPromotionGateReasons(item, reasons) {
+  if (!validatorPassed(item)) {
+    reasons.push('strict_validator_pass_required_for_promotion');
+  }
+  if (!hasEvidenceBundle(item)) {
+    reasons.push('evidence_bundle_required_for_promotion');
+  }
+}
+
+function acceptedEligibility(item) {
+  const reasons = [];
+  addPromotionGateReasons(item, reasons);
+  const missing = missingProvenanceFields(item, ACCEPTED_REQUIRED_PROVENANCE_FIELDS);
+  if (missing.length > 0) {
+    reasons.push('accepted_provenance_required_fields_missing');
+  }
+  if (!meetsEvidenceThreshold(item, 'accepted')) {
+    reasons.push('accepted_triangulation_or_official_source_requirements_missing');
+  }
+  if (item?.risk_tier === LOW_RISK_TIER && item?.official_source_backed !== true) {
+    reasons.push('low_risk_acceptance_requires_official_source');
+  }
+  if (!hasSampledQaOrReview(item)) {
+    reasons.push('accepted_requires_sampled_qa_or_human_review');
+  }
+  return {
+    eligible: reasons.length === 0,
+    reasons,
+    missing_provenance_fields: missing,
+  };
+}
+
+function provisionalEligibility(item) {
+  const reasons = [];
+  addPromotionGateReasons(item, reasons);
+  const missing = missingProvenanceFields(item, PROVISIONAL_REQUIRED_PROVENANCE_FIELDS);
+  if (missing.length > 0) {
+    reasons.push('provisional_safe_provenance_required_fields_missing');
+  }
+  if (!meetsEvidenceThreshold(item, 'provisional_safe')) {
+    reasons.push('provisional_safe_triangulation_requirements_missing');
+  }
+  return {
+    eligible: reasons.length === 0,
+    reasons,
+    missing_provenance_fields: missing,
+  };
+}
+
+function assertionLayerBase({ item, layer, decision, reasonCodes, extra = {} }) {
+  return {
+    promotion_assertion_id: `semkg-promotion:${ISSUE}:${item?.assertion_id ?? item?.blocker_id}`,
+    assertion_id: item?.assertion_id ?? null,
+    source_classification_id: item?.classification_id ?? null,
+    question_row_id: item?.question_row_id ?? null,
+    predicate: item?.predicate ?? null,
+    edge_type: item?.edge_type ?? item?.predicate ?? null,
+    subject_ref: item?.subject_ref ?? null,
+    object_ref: item?.object_ref ?? null,
+    scope_ref: item?.scope_ref ?? null,
+    source_status: item?.source_status ?? item?.status ?? null,
+    source_classification_status: item?.classification_status ?? null,
+    source_layer: item?.layer ?? null,
+    source_route: item?.route ?? null,
+    risk_tier: item?.risk_tier ?? null,
+    confidence: item?.confidence ?? null,
+    evidence_families: evidenceFamilies(item),
+    evidence_bundle: item?.evidence_bundle ?? null,
+    provenance: item?.provenance ?? null,
+    layer,
+    promotion_decision: decision,
+    reason_codes: uniqueSorted(reasonCodes),
+    source_row_ref: item?.source_row_ref ?? null,
+    promotion_allowed: layer === 'accepted' || layer === 'provisional_safe',
+    accepted_edge: layer === 'accepted',
+    runtime_consumption_allowed: layer === 'accepted',
+    ...extra,
+  };
+}
+
+function routeAssertion(item) {
+  const reasonCodes = Array.isArray(item?.reason_codes) ? [...item.reason_codes] : [];
+  if (!isObject(item)) {
+    return {
+      layer: 'review_required',
+      decision: 'review_required',
+      reasonCodes: ['classification_assertion_malformed'],
+      extra: {
+        promotion_allowed: false,
+        accepted_edge: false,
+        runtime_consumption_allowed: false,
+      },
+    };
+  }
+  if (isBlockedLike(item)) {
+    reasonCodes.push('blocked_quarantined_status_categorically_excluded');
+    return {
+      layer: 'blocked_quarantined',
+      decision: 'blocked_quarantined',
+      reasonCodes,
+      extra: {
+        source_confidence_ignored: item.confidence ?? null,
+        promotion_allowed: false,
+        accepted_edge: false,
+        runtime_consumption_allowed: false,
+      },
+    };
+  }
+  if (isRejectedLike(item)) {
+    reasonCodes.push('explicit_rejected_state');
+    return {
+      layer: 'rejected',
+      decision: 'rejected',
+      reasonCodes,
+      extra: {
+        promotion_allowed: false,
+        accepted_edge: false,
+        runtime_consumption_allowed: false,
+      },
+    };
+  }
+  if (isRawCandidateLike(item)) {
+    reasonCodes.push('raw_candidate_excluded_from_promoted_layers');
+    if (item?.route === 'candidate_hold') {
+      reasonCodes.push('candidate_hold_requires_review');
+    }
+    return {
+      layer: 'review_required',
+      decision: 'review_required',
+      reasonCodes,
+      extra: {
+        promotion_allowed: false,
+        accepted_edge: false,
+        runtime_consumption_allowed: false,
+      },
+    };
+  }
+  if (hasContradiction(item)) {
+    reasonCodes.push('contradiction_or_conflict_requires_review');
+    return {
+      layer: 'review_required',
+      decision: 'review_required',
+      reasonCodes,
+      extra: {
+        promotion_allowed: false,
+        accepted_edge: false,
+        runtime_consumption_allowed: false,
+      },
+    };
+  }
+  if (isHighRiskAssertion(item)) {
+    reasonCodes.push('high_risk_edge_requires_human_review');
+    reasonCodes.push('high_risk_edges_must_not_auto_accept_v1');
+    return {
+      layer: item?.classification_status === 'provisional_safe' ? 'provisional_safe' : 'review_required',
+      decision: item?.classification_status === 'provisional_safe' ? 'provisional_safe' : 'review_required',
+      reasonCodes,
+      extra: item?.classification_status === 'provisional_safe'
+        ? {
+          promotion_allowed: true,
+          accepted_edge: false,
+          runtime_consumption_allowed: false,
+        }
+        : {
+          promotion_allowed: false,
+          accepted_edge: false,
+          runtime_consumption_allowed: false,
+        },
+    };
+  }
+
+  if (item?.classification_status === 'accepted' || item?.source_status === 'accepted') {
+    const eligibility = acceptedEligibility(item);
+    if (eligibility.eligible) {
+      return {
+        layer: 'accepted',
+        decision: 'accepted',
+        reasonCodes,
+        extra: {
+          missing_provenance_fields: eligibility.missing_provenance_fields,
+        },
+      };
+    }
+    return {
+      layer: 'review_required',
+      decision: 'review_required',
+      reasonCodes: [...reasonCodes, ...eligibility.reasons],
+      extra: {
+        missing_provenance_fields: eligibility.missing_provenance_fields,
+        promotion_allowed: false,
+        accepted_edge: false,
+        runtime_consumption_allowed: false,
+      },
+    };
+  }
+
+  if (
+    item?.classification_status === 'provisional_safe' ||
+    item?.source_status === 'provisional_safe' ||
+    item?.classification_status === 'triangulated_candidate' ||
+    item?.source_status === 'triangulated_candidate'
+  ) {
+    const eligibility = provisionalEligibility(item);
+    if (eligibility.eligible) {
+      return {
+        layer: 'provisional_safe',
+        decision: 'provisional_safe',
+        reasonCodes,
+        extra: {
+          missing_provenance_fields: eligibility.missing_provenance_fields,
+          promotion_allowed: true,
+          accepted_edge: false,
+          runtime_consumption_allowed: false,
+        },
+      };
+    }
+    return {
+      layer: 'review_required',
+      decision: 'review_required',
+      reasonCodes: [...reasonCodes, ...eligibility.reasons],
+      extra: {
+        missing_provenance_fields: eligibility.missing_provenance_fields,
+        promotion_allowed: false,
+        accepted_edge: false,
+        runtime_consumption_allowed: false,
+      },
+    };
+  }
+
+  reasonCodes.push('source_state_not_promotion_eligible');
+  return {
+    layer: 'review_required',
+    decision: 'review_required',
+    reasonCodes,
+    extra: {
+      promotion_allowed: false,
+      accepted_edge: false,
+      runtime_consumption_allowed: false,
+    },
+  };
+}
+
+function terminalBlockerLayerEntry({ blocker, row }) {
+  const reasonCodes = uniqueSorted([
+    ...(Array.isArray(blocker?.reason_codes) ? blocker.reason_codes : []),
+    'blocked_quarantined_status_categorically_excluded',
+  ]);
+  return {
+    promotion_assertion_id:
+      `semkg-promotion:${ISSUE}:terminal:${row.question_row_id}:${blocker?.blocker_id ?? 'blocker'}`,
+    assertion_id: null,
+    assertion_kind: 'terminal_blocker',
+    source_classification_id: blocker?.classification_id ?? null,
+    source_blocker_id: blocker?.blocker_id ?? null,
+    question_row_id: row.question_row_id,
+    source_status: blocker?.source_status ?? blocker?.status ?? 'blocked_quarantined',
+    source_classification_status: blocker?.classification_status ?? null,
+    source_route: blocker?.route ?? null,
+    blocker_category: blocker?.blocker_category ?? null,
+    terminal_state: blocker?.terminal_state ?? null,
+    support_state: blocker?.support_state ?? null,
+    source_confidence_ignored: blocker?.confidence ?? blocker?.source_confidence_ignored ?? null,
+    layer: 'blocked_quarantined',
+    promotion_decision: 'blocked_quarantined',
+    reason_codes: reasonCodes,
+    source_row_ref: blocker?.source_row_ref ?? row.source_row_ref ?? null,
+    promotion_allowed: false,
+    accepted_edge: false,
+    runtime_consumption_allowed: false,
+  };
+}
+
+function sortLayerEntries(items) {
+  return [...items].sort((left, right) => (
+    compareByteOrder(
+      left.assertion_id ?? left.source_blocker_id ?? left.promotion_assertion_id,
+      right.assertion_id ?? right.source_blocker_id ?? right.promotion_assertion_id,
+    ) ||
+    compareByteOrder(left.question_row_id, right.question_row_id) ||
+    compareByteOrder(left.promotion_assertion_id, right.promotion_assertion_id)
+  ));
+}
+
+function buildLayers(rows) {
+  const accepted = [];
+  const provisionalSafe = [];
+  const reviewRequired = [];
+  const rejected = [];
+  const blockedQuarantined = [];
+
+  for (const row of rows) {
+    for (const item of row.classified_assertions) {
+      const routed = routeAssertion(item);
+      const entry = assertionLayerBase({
+        item,
+        layer: routed.layer,
+        decision: routed.decision,
+        reasonCodes: routed.reasonCodes,
+        extra: routed.extra,
+      });
+      if (routed.layer === 'accepted') accepted.push(entry);
+      else if (routed.layer === 'provisional_safe') provisionalSafe.push(entry);
+      else if (routed.layer === 'rejected') rejected.push(entry);
+      else if (routed.layer === 'blocked_quarantined') blockedQuarantined.push(entry);
+      else reviewRequired.push(entry);
+    }
+    for (const blocker of row.terminal_blocker_classifications) {
+      blockedQuarantined.push(terminalBlockerLayerEntry({ blocker, row }));
+    }
+  }
+
+  return {
+    accepted: sortLayerEntries(accepted),
+    provisionalSafe: sortLayerEntries(provisionalSafe),
+    reviewRequired: sortLayerEntries(reviewRequired),
+    rejected: sortLayerEntries(rejected),
+    blockedQuarantined: sortLayerEntries(blockedQuarantined),
+  };
+}
+
+function buildSummary({ rows, layers, classification }) {
+  const assertions = rows.flatMap((row) => row.classified_assertions);
+  const blockers = rows.flatMap((row) => row.terminal_blocker_classifications);
+  return {
+    represented_row_count: rows.length,
+    source_represented_row_count: classification?.summary?.represented_row_count ?? rows.length,
+    raw_candidate_assertion_count: assertions.filter((item) => isRawCandidateLike(item)).length,
+    classified_assertion_count: assertions.length,
+    terminal_blocker_count: blockers.length,
+    accepted_count: layers.accepted.length,
+    provisional_safe_count: layers.provisionalSafe.length,
+    review_required_count: layers.reviewRequired.length,
+    rejected_count: layers.rejected.length,
+    blocked_quarantined_count: layers.blockedQuarantined.length,
+    layer_entry_count:
+      layers.accepted.length +
+      layers.provisionalSafe.length +
+      layers.reviewRequired.length +
+      layers.rejected.length +
+      layers.blockedQuarantined.length,
+    no_auth_receipt_count: classification?.summary?.no_auth_receipt_count ?? 0,
+    contradiction_count:
+      assertions.filter((item) => hasContradiction(item)).length,
+    high_risk_review_required_count:
+      layers.reviewRequired.filter((item) => isHighRiskAssertion(item)).length,
+    external_model_call_count: 0,
+    layer_counts: {
+      accepted: layers.accepted.length,
+      provisional_safe: layers.provisionalSafe.length,
+      review_required: layers.reviewRequired.length,
+      rejected: layers.rejected.length,
+      blocked_quarantined: layers.blockedQuarantined.length,
+    },
+    source_classification_status_counts: countBy([
+      ...assertions,
+      ...blockers,
+    ], 'classification_status'),
+    promotion_layer_counts: {
+      accepted: layers.accepted.length,
+      provisional_safe: layers.provisionalSafe.length,
+      review_required: layers.reviewRequired.length,
+      rejected: layers.rejected.length,
+      blocked_quarantined: layers.blockedQuarantined.length,
+    },
+  };
+}
+
+function buildLayerArtifact({ layerName, artifactPath, generatedAt, sourcePath, assertions }) {
+  return {
+    schema_version: `semantic_kg_${layerName}_layer.v1`,
+    generated_at: generatedAt,
+    generated_by: SCRIPT_NAME,
+    issue: ISSUE,
+    parent_issue: PARENT_ISSUE,
+    source_promotion_gate_path: sourcePath,
+    layer: layerName,
+    summary: {
+      assertion_count: assertions.length,
+      external_model_call_count: 0,
+    },
+    assertions,
+    content_hash: {
+      algorithm: 'sha256',
+      value: sha256Value({
+        layer: layerName,
+        assertion_ids: assertions.map((item) => (
+          item.assertion_id ?? item.source_blocker_id ?? item.promotion_assertion_id
+        )),
+        artifact_path: artifactPath,
+      }),
+    },
+  };
+}
+
+function buildPromotionGate({ generatedAt, paths, source, layers, summary }) {
+  return {
+    schema_version: 'semantic_kg_promotion_gate.v1',
+    generated_at: generatedAt,
+    generated_by: SCRIPT_NAME,
+    issue: ISSUE,
+    parent_issue: PARENT_ISSUE,
+    depends_on_issues: DEPENDS_ON_ISSUES,
+    subject_code: SUBJECT_CODE,
+    objective:
+      'Promote only validated semantic KG assertions into separated provisional_safe and accepted layers.',
+    boundary: buildBoundary(paths),
+    source_contract: source,
+    output_artifacts: {
+      promotion_gate: paths.promotionGateOut,
+      accepted_layer: paths.acceptedLayerOut,
+      provisional_safe_layer: paths.provisionalSafeLayerOut,
+      review_required_layer: paths.reviewRequiredLayerOut,
+      rejected_layer: paths.rejectedLayerOut,
+      blocked_quarantined_layer: paths.blockedQuarantinedLayerOut,
+      validator_result: paths.validatorOut,
+      readback: paths.readbackOut,
+    },
+    promotion_policy: {
+      fail_closed_if_upstream_classification_missing_malformed_or_failed: true,
+      raw_candidates_cannot_enter_accepted_or_provisional_safe: true,
+      blocked_quarantined_cannot_be_promoted_by_confidence: true,
+      accepted_requires_non_raw_non_blocked_non_rejected_conflict_free_assertion: true,
+      accepted_requires_provenance_evidence_bundle_validator_and_triangulation: true,
+      low_risk_descriptive_edges_require_official_source_for_acceptance: true,
+      high_risk_prerequisite_misconception_mastery_no_auto_accept_v1: true,
+      provisional_safe_requires_non_raw_non_blocked_non_rejected_validator_clean_assertion: true,
+    },
+    summary,
+    layer_summaries: {
+      accepted: {
+        path: paths.acceptedLayerOut,
+        assertion_count: layers.accepted.length,
+      },
+      provisional_safe: {
+        path: paths.provisionalSafeLayerOut,
+        assertion_count: layers.provisionalSafe.length,
+      },
+      review_required: {
+        path: paths.reviewRequiredLayerOut,
+        assertion_count: layers.reviewRequired.length,
+      },
+      rejected: {
+        path: paths.rejectedLayerOut,
+        assertion_count: layers.rejected.length,
+      },
+      blocked_quarantined: {
+        path: paths.blockedQuarantinedLayerOut,
+        assertion_count: layers.blockedQuarantined.length,
+      },
+    },
+    promoted_assertion_ids: {
+      accepted: layers.accepted.map((item) => item.assertion_id),
+      provisional_safe: layers.provisionalSafe.map((item) => item.assertion_id),
+    },
+    content_hash: {
+      algorithm: 'sha256',
+      value: sha256Value({
+        issue: ISSUE,
+        summary,
+        accepted: layers.accepted.map((item) => item.assertion_id),
+        provisional_safe: layers.provisionalSafe.map((item) => item.assertion_id),
+        review_required: layers.reviewRequired.map((item) => item.assertion_id),
+        rejected: layers.rejected.map((item) => item.assertion_id),
+        blocked_quarantined: layers.blockedQuarantined.map((item) => (
+          item.assertion_id ?? item.source_blocker_id ?? item.promotion_assertion_id
+        )),
+      }),
+    },
+  };
+}
+
+function sameList(left, right) {
+  return JSON.stringify(left) === JSON.stringify(right);
+}
+
+function passCheck(id, evidence = {}) {
+  return { id, status: 'pass', evidence };
+}
+
+function failCheck(id, reason, evidence = {}) {
+  return { id, status: 'fail', reason, evidence };
+}
+
+function isSortedById(items) {
+  const ids = items.map((item) => (
+    item.assertion_id ?? item.source_blocker_id ?? item.promotion_assertion_id
+  ));
+  return sameList(ids, [...ids].sort(compareByteOrder));
+}
